<?php declare(strict_types=1);namespace TypePhp\MicroFw\Http\Message{interface StreamInterface{public function __toString():string;public function getContents():string;public function getSize():int;}}namespace TypePhp\MicroFw\Http\Message{interface MessageInterface{public function getProtocolVersion():string;public function getHeaders():array;public function hasHeader(string $name):bool;public function getHeaderLine(string $name):string;public function withHeader(string $name,string $value):MessageInterface;public function getBody():StreamInterface;public function withBody(StreamInterface $body):MessageInterface;}}namespace TypePhp\MicroFw\Http\Message{interface UriInterface{public function getScheme():string;public function getHost():string;public function getPath():string;public function getQuery():string;}}namespace TypePhp\MicroFw\Http\Message{interface RequestInterface extends MessageInterface{public function getMethod():string;public function getUri():UriInterface;}}namespace TypePhp\MicroFw\Http\Message{interface ServerRequestInterface extends RequestInterface{public function getQueryParams():array;public function getParsedBody():mixed;public function getAttribute(string $name):mixed;public function withAttribute(string $name,mixed $value):ServerRequestInterface;}}namespace TypePhp\MicroFw\Http\Message{interface ResponseInterface extends MessageInterface{public function getStatusCode():int;public function getReasonPhrase():string;public function withStatus(int $code,string $reasonPhrase=''):ResponseInterface;}}namespace TypePhp\MicroFw\Http\Message{class ServerRequest implements ServerRequestInterface{private string $method;private UriInterface $uri;private array $headers;private StreamInterface $body;private array $queryParams;private mixed $parsedBody;private array $attributes;public function __construct(string $a,UriInterface $b,array $c,StreamInterface $d,array $e,mixed $f,array $g){$this->method=strtoupper($a);$this->uri=$b;$this->headers=$c;$this->body=$d;$this->queryParams=$e;$this->parsedBody=$f;$this->attributes=$g;}public function getProtocolVersion():string{return '1.1';}public function getMethod():string{return $this->method;}public function getUri():UriInterface{return $this->uri;}public function getHeaders():array{return $this->headers;}public function hasHeader(string $a):bool{return array_key_exists(strtolower($a),$this->headers);}public function getHeaderLine(string $a):string{$b=strtolower($a);if(array_key_exists($b,$this->headers)){return $this->headers[$b];}return '';}public function withHeader(string $a,string $b):MessageInterface{$c=$this->headers;$c[strtolower($a)]=$b;return new ServerRequest($this->method,$this->uri,$c,$this->body,$this->queryParams,$this->parsedBody,$this->attributes);}public function getBody():StreamInterface{return $this->body;}public function withBody(StreamInterface $a):MessageInterface{return new ServerRequest($this->method,$this->uri,$this->headers,$a,$this->queryParams,$this->parsedBody,$this->attributes);}public function getQueryParams():array{return $this->queryParams;}public function getParsedBody():mixed{return $this->parsedBody;}public function getAttribute(string $a):mixed{if(array_key_exists($a,$this->attributes)){return $this->attributes[$a];}return null;}public function withAttribute(string $a,mixed $b):ServerRequestInterface{$c=$this->attributes;$c[$a]=$b;return new ServerRequest($this->method,$this->uri,$this->headers,$this->body,$this->queryParams,$this->parsedBody,$c);}}}namespace TypePhp\MicroFw\Http\Message{class Response implements ResponseInterface{private int $statusCode;private string $reasonPhrase;private array $headers;private StreamInterface $body;public function __construct(int $a,array $b,StreamInterface $c,string $d=''){$this->statusCode=$a;$this->headers=$b;$this->body=$c;$this->reasonPhrase=$d;}public function getProtocolVersion():string{return '1.1';}public function getStatusCode():int{return $this->statusCode;}public function getReasonPhrase():string{return $this->reasonPhrase;}public function getHeaders():array{return $this->headers;}public function hasHeader(string $a):bool{return array_key_exists(strtolower($a),$this->headers);}public function getHeaderLine(string $a):string{$b=strtolower($a);if(array_key_exists($b,$this->headers)){return $this->headers[$b];}return '';}public function withHeader(string $a,string $b):MessageInterface{$c=$this->headers;$c[strtolower($a)]=$b;return new Response($this->statusCode,$c,$this->body,$this->reasonPhrase);}public function getBody():StreamInterface{return $this->body;}public function withBody(StreamInterface $a):MessageInterface{return new Response($this->statusCode,$this->headers,$a,$this->reasonPhrase);}public function withStatus(int $a,string $b=''):ResponseInterface{return new Response($a,$this->headers,$this->body,$b);}}}namespace TypePhp\MicroFw\Http\Message{class StringStream implements StreamInterface{private string $content;public function __construct(string $a=''){$this->content=$a;}public function __toString():string{return $this->content;}public function getContents():string{return $this->content;}public function getSize():int{return strlen($this->content);}}}namespace TypePhp\MicroFw\Http\Message{class Uri implements UriInterface{private string $scheme;private string $host;private string $path;private string $query;public function __construct(string $a,string $b,string $c,string $d=''){$this->scheme=$a;$this->host=$b;$this->path=$c;$this->query=$d;}public function getScheme():string{return $this->scheme;}public function getHost():string{return $this->host;}public function getPath():string{return $this->path;}public function getQuery():string{return $this->query;}}}namespace TypePhp\MicroFw\Routing{use TypePhp\MicroFw\Http\Message\ServerRequestInterface;use TypePhp\MicroFw\Http\Message\ResponseInterface;use TypePhp\MicroFw\Http\Message\Response;use TypePhp\MicroFw\Http\Message\StringStream;class App{private array $routes;private array $middlewares;public function __construct(){$this->routes=[];$this->middlewares=[];}public function addMiddleware(\Closure $a):void{array_push($this->middlewares,$a);}public function get(string $a,\Closure $b):void{$c=['method'=>'GET','path'=>$a,'handler'=>$b];array_push($this->routes,$c);}public function post(string $a,\Closure $b):void{$c=['method'=>'POST','path'=>$a,'handler'=>$b];array_push($this->routes,$c);}public function put(string $a,\Closure $b):void{$c=['method'=>'PUT','path'=>$a,'handler'=>$b];array_push($this->routes,$c);}public function delete(string $a,\Closure $b):void{$c=['method'=>'DELETE','path'=>$a,'handler'=>$b];array_push($this->routes,$c);}public function handle(ServerRequestInterface $a):ResponseInterface{$b=fn(ServerRequestInterface $b):ResponseInterface=>$this->dispatch($b);$c=$b;foreach($this->middlewares as $d){$e=$c;$f=$d;$c=fn(ServerRequestInterface $g):ResponseInterface=>$f($g,$e);}return $c($a);}private function dispatch(ServerRequestInterface $a):ResponseInterface{$b=$a->getMethod();$c=$a->getUri()->getPath();foreach($this->routes as $d){if($d['method']===$b&&$d['path']===$c){$e=$d['handler'];return $e($a);}}$f=new StringStream((string)json_encode(['ok'=>false,'error'=>'Route not found']));return new Response(404,['content-type'=>'application/json; charset=utf-8'],$f);}public function emit(ResponseInterface $a):void{http_response_code($a->getStatusCode());foreach($a->getHeaders()as $b=>$c){header($b.': '.$c);}echo $a->getBody()->getContents();}}}namespace TypePhp\MicroFw\Validation{class ValidationResult{private bool $valid;private array $errors;private array $data;public function __construct(bool $a,array $b,array $c){$this->valid=$a;$this->errors=$b;$this->data=$c;}public function isValid():bool{return $this->valid;}public function getErrors():array{return $this->errors;}public function getData():array{return $this->data;}}}namespace TypePhp\MicroFw\Validation{class Validator{private function checkSingleRule(string $a,mixed $b,string $c,bool $d):?string{if($c==='string'){if(!is_string($b)){return $a.' must be a string';}if($d&&trim($b)===''){return $a.' cannot be empty';}}elseif($c==='int'){if(!is_int($b)){return $a.' must be an integer';}}elseif($c==='bool'){if(!is_bool($b)){return $a.' must be a boolean';}}elseif(str_starts_with($c,'min:')){$e=intval(substr($c,4));if(is_string($b)){if(strlen(trim($b))<$e){return $a.' must be at least '.(string)$e.' characters';}}}elseif(str_starts_with($c,'max:')){$f=intval(substr($c,4));if(is_string($b)){if(strlen(trim($b))>$f){return $a.' must be at most '.(string)$f.' characters';}}}return null;}private function validateField(string $a,mixed $b,string $c):?string{$d=explode('|',$c);$e=false;foreach($d as $f){if($f==='required'){$e=true;}}foreach($d as $g){$h=$this->checkSingleRule($a,$b,$g,$e);if($h!==null){return $h;}}return null;}public function validate(mixed $a,array $b):ValidationResult{$c=[];$d=[];if(!is_array($a)){$c['_body']='Request body must be a JSON object';return new ValidationResult(false,$c,$d);}foreach($b as $e=>$f){$g=(string)$e;$h=array_key_exists($g,$a);$i=null;if($h){$i=$a[$g];}$j=explode('|',$f);$k=false;foreach($j as $l){if($l==='required'){$k=true;}}if(!$h||$i===null){if($k){$c[$g]=$g.' is required';}}else{$m=$this->validateField($g,$i,$f);if($m!==null){$c[$g]=$m;}elseif(is_string($i)){$d[$g]=trim($i);}else{$d[$g]=$i;}}}$n=true;foreach($c as $o=>$p){$n=false;}return new ValidationResult($n,$c,$d);}}}namespace TypePhp\BlogApp\Repository{use PDO;use PDOStatement;class PostRepository{private PDO $pdo;public function __construct(string $a){$this->pdo=new PDO('sqlite:'.$a);$this->pdo->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$this->pdo->exec('CREATE TABLE IF NOT EXISTS posts (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                slug TEXT NOT NULL,
                content TEXT NOT NULL,
                published INTEGER NOT NULL DEFAULT 0,
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
            )');}public function findPublished():array{$a=$this->pdo->prepare('SELECT id, title, slug, content, published, created_at FROM posts WHERE published = 1 ORDER BY id DESC');$a->execute([]);return $a->fetchAll(PDO::FETCH_ASSOC);}public function findAll():array{$a=$this->pdo->prepare('SELECT id, title, slug, content, published, created_at FROM posts ORDER BY id DESC');$a->execute([]);return $a->fetchAll(PDO::FETCH_ASSOC);}public function findById(int $a):mixed{$b=$this->pdo->prepare('SELECT id, title, slug, content, published, created_at FROM posts WHERE id = ?');$b->execute([$a]);return $b->fetch(PDO::FETCH_ASSOC);}public function create(string $a,string $b,string $c,int $d):mixed{$e=$this->pdo->prepare('INSERT INTO posts (title, slug, content, published) VALUES (?, ?, ?, ?)');$e->execute([$a,$b,$c,$d]);$f=intval($this->pdo->lastInsertId());return $this->findById($f);}public function update(int $a,string $b,string $c,string $d,int $e):bool{$f=$this->pdo->prepare('UPDATE posts SET title = ?, slug = ?, content = ?, published = ? WHERE id = ?');$f->execute([$b,$c,$d,$e,$a]);return $f->rowCount()>0;}public function delete(int $a):bool{$b=$this->pdo->prepare('DELETE FROM posts WHERE id = ?');$b->execute([$a]);return $b->rowCount()>0;}}}namespace TypePhp\BlogApp\View{class Templates{private function layout(string $a,string $b):string{return '<!DOCTYPE html><html lang="vi"><head><meta charset="UTF-8" /><meta name="viewport" content="width=device-width, initial-scale=1.0" /><title>'.htmlspecialchars($a).'</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-slate-50 text-slate-800 min-h-screen flex flex-col"><header class="bg-white border-b border-slate-200 sticky top-0 z-10"><div class="max-w-5xl mx-auto px-4 py-4 flex items-center justify-between"><a href="/" class="text-xl font-bold text-indigo-600 tracking-tight">TypePHP Blog</a><nav class="flex items-center gap-4 text-sm font-medium"><a href="/" class="text-slate-600 hover:text-indigo-600 transition">Blog</a><a href="/admin" class="px-3 py-1.5 rounded-lg bg-indigo-600 text-white hover:bg-indigo-700 transition">Admin</a></nav></div></header><main class="max-w-5xl w-full mx-auto px-4 py-8 flex-1">'.$b.'</main>
    <footer class="border-t border-slate-200 bg-white py-4 text-center text-xs text-slate-400">
        Powered by TypePHP PSR-7 Micro-Framework &amp; SQLite
    </footer>
</body>
</html>';}private function safeStr(mixed $a):string{if(is_string($a)){return htmlspecialchars($a);}if(is_int($a)){return(string)$a;}return '';}public function renderBlogPage(array $a):string{$b='';$c=0;foreach($a as $d){if(is_array($d)){$c=$c+1;$e=$this->safeStr($d['id']??0);$f=$this->safeStr($d['title']??'');$g=$this->safeStr($d['slug']??'');$h=$this->safeStr($d['content']??'');$i=$this->safeStr($d['created_at']??'');$b=$b.'<article class="bg-white rounded-xl border border-slate-200 p-6 shadow-sm hover:shadow-md transition"><div class="flex items-center justify-between text-xs text-slate-400 mb-2"><span class="font-mono bg-slate-100 text-slate-600 px-2 py-0.5 rounded">/'.$g.'</span>
                        <span>'.$i.'</span></div><h2 class="text-xl font-bold text-slate-900 mb-2"><a href="/post?id='.$e.'" class="hover:text-indigo-600 transition">'.$f.'</a>
                    </h2>
                    <p class="text-slate-600 text-sm leading-relaxed mb-4">'.$h.'</p>
                    <a href="/post?id='.$e.'" class="text-sm font-semibold text-indigo-600 hover:text-indigo-800">Đọc tiếp &rarr;</a></article>';}}if($c===0){$b='<div class="bg-white rounded-xl border border-dashed border-slate-300 p-12 text-center"><p class="text-slate-500 mb-4">Chưa có bài viết nào được xuất bản.</p><a href="/admin" class="inline-block px-4 py-2 rounded-lg bg-indigo-600 text-white text-sm font-medium hover:bg-indigo-700">Vào trang Admin tạo bài viết</a></div>';}$j='<div class="mb-8"><h1 class="text-3xl font-extrabold text-slate-900">Bài viết mới nhất</h1><p class="text-slate-500 mt-1">Ứng dụng Blog viết bằng TypePHP + Tailwind CSS + SQLite</p></div><div class="grid gap-6">'.$b.'</div>';return $this->layout('TypePHP Blog',$j);}public function renderPostDetailPage(mixed $a):string{if(!is_array($a)){$b='<div class="bg-white rounded-xl border border-slate-200 p-8 text-center"><h1 class="text-2xl font-bold text-slate-900 mb-2">Không tìm thấy bài viết</h1><a href="/" class="text-indigo-600 hover:underline text-sm">&larr; Quay lại trang chủ</a></div>';return $this->layout('404 - TypePHP Blog',$b);}$c=$this->safeStr($a['title']??'');$d=$this->safeStr($a['slug']??'');$e=$this->safeStr($a['content']??'');$f=$this->safeStr($a['created_at']??'');$g='<div class="mb-6"><a href="/" class="text-sm text-indigo-600 hover:underline">&larr; Quay lại danh sách</a></div><article class="bg-white rounded-xl border border-slate-200 p-8 shadow-sm"><div class="flex items-center gap-3 text-xs text-slate-400 mb-3"><span class="font-mono bg-slate-100 text-slate-600 px-2 py-0.5 rounded">/'.$d.'</span>
                <span>'.$f.'</span></div><h1 class="text-3xl font-extrabold text-slate-900 mb-6">'.$c.'</h1>
            <div class="text-slate-700 leading-relaxed whitespace-pre-line">'.$e.'</div></article>';return $this->layout($c.' - TypePHP Blog',$g);}public function renderLoginPage(string $a=''):string{$b='';if($a!==''){$b='<div class="mb-4 p-3 rounded-lg bg-red-50 border border-red-200 text-red-700 text-sm">'.htmlspecialchars($a).'</div>';}$c='<div class="max-w-md mx-auto bg-white rounded-xl border border-slate-200 p-8 shadow-sm mt-8"><h1 class="text-2xl font-extrabold text-slate-900 mb-2">Đăng nhập Admin</h1><p class="text-xs text-slate-500 mb-6">Tài khoản mặc định: <span class="font-mono bg-slate-100 px-1.5 py-0.5 rounded">admin</span> / <span class="font-mono bg-slate-100 px-1.5 py-0.5 rounded">admin123</span></p>'.$b.'<form id="loginForm" class="space-y-4"><div><label class="block text-xs font-semibold text-slate-700 mb-1">Tên đăng nhập</label><input id="username" type="text" value="admin" required class="w-full px-3 py-2 text-sm border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500" /></div><div><label class="block text-xs font-semibold text-slate-700 mb-1">Mật khẩu</label><input id="password" type="password" value="admin123" required class="w-full px-3 py-2 text-sm border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500" /></div><button type="submit" class="w-full px-4 py-2 rounded-lg bg-indigo-600 text-white text-sm font-semibold hover:bg-indigo-700 transition">Đăng nhập</button></form><div id="loginErr" class="hidden mt-4 p-3 rounded-lg bg-red-50 border border-red-200 text-red-700 text-xs"></div></div><script>document.getElementById("loginForm").addEventListener("submit",async(e)=>{e.preventDefault();const res=await fetch("/api/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({username:document.getElementById("username").value,password:document.getElementById("password").value})});const json=await res.json();if(json.ok){window.location.href="/admin";}else{const box=document.getElementById("loginErr");box.textContent=json.error||"Đăng nhập thất bại";box.classList.remove("hidden");}});</script>';return $this->layout('Đăng nhập Admin - TypePHP Blog',$c);}public function renderAdminPage():string{$a='<div class="flex flex-col md:flex-row md:items-center md:justify-between gap-4 mb-8"><div><h1 class="text-3xl font-extrabold text-slate-900">Blog Admin</h1><p class="text-slate-500 text-sm mt-1">Quản lý bài viết qua PSR-7 API &amp; Validator</p></div><div class="flex items-center gap-3"><span class="text-xs px-2.5 py-1 rounded-full bg-emerald-50 text-emerald-700 font-medium">Đã đăng nhập: admin</span><button id="logoutBtn" class="px-3 py-1.5 text-xs font-medium rounded-lg bg-slate-200 hover:bg-slate-300 text-slate-700 transition">Đăng xuất</button></div></div><div class="grid md:grid-cols-3 gap-8"><section class="md:col-span-1 bg-white rounded-xl border border-slate-200 p-6 shadow-sm h-fit"><h2 id="formTitle" class="text-lg font-bold text-slate-900 mb-4">Tạo bài viết mới</h2><div id="errorBox" class="hidden mb-4 p-3 rounded-lg bg-red-50 border border-red-200 text-red-700 text-xs space-y-1"></div><form id="postForm" class="space-y-4"><input type="hidden" id="postId" value="" /><div><label class="block text-xs font-semibold text-slate-700 mb-1">Tiêu đề</label><input id="title" type="text" placeholder="Ví dụ: Giới thiệu TypePHP" class="w-full px-3 py-2 text-sm border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500" /></div><div><label class="block text-xs font-semibold text-slate-700 mb-1">Slug</label><input id="slug" type="text" placeholder="gioi-thieu-typephp" class="w-full px-3 py-2 text-sm border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500" /></div><div><label class="block text-xs font-semibold text-slate-700 mb-1">Nội dung</label><textarea id="content" rows="5" placeholder="Nội dung tối thiểu 10 ký tự..." class="w-full px-3 py-2 text-sm border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500"></textarea></div><label class="flex items-center gap-2 text-sm text-slate-700 cursor-pointer"><input id="published" type="checkbox" checked class="rounded text-indigo-600" /><span>Xuất bản ngay</span></label><div class="flex gap-2"><button type="submit" class="flex-1 px-4 py-2 rounded-lg bg-indigo-600 text-white text-sm font-semibold hover:bg-indigo-700 transition">Lưu bài viết</button><button type="button" id="cancelEdit" class="hidden px-3 py-2 rounded-lg bg-slate-100 text-slate-700 text-sm hover:bg-slate-200">Huỷ</button></div></form></section><section class="md:col-span-2 bg-white rounded-xl border border-slate-200 p-6 shadow-sm"><div class="flex items-center justify-between mb-4"><h2 class="text-lg font-bold text-slate-900">Danh sách bài viết</h2><button id="refreshBtn" class="text-xs px-3 py-1.5 rounded-lg bg-slate-100 hover:bg-slate-200 text-slate-700 font-medium">Làm mới</button></div><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead><tr class="border-b border-slate-200 text-xs text-slate-500 uppercase"><th class="py-2 pr-3">ID</th><th class="py-2 pr-3">Tiêu đề</th><th class="py-2 pr-3">Trạng thái</th><th class="py-2 text-right">Thao tác</th></tr></thead><tbody id="postsBody" class="divide-y divide-slate-100"></tbody></table></div></section></div><script>const form=document.getElementById("postForm");const errorBox=document.getElementById("errorBox");const postsBody=document.getElementById("postsBody");const postIdEl=document.getElementById("postId");const titleEl=document.getElementById("title");const slugEl=document.getElementById("slug");const contentEl=document.getElementById("content");const publishedEl=document.getElementById("published");const formTitle=document.getElementById("formTitle");const cancelEdit=document.getElementById("cancelEdit");function headers(){return{"Content-Type":"application/json"};}document.getElementById("logoutBtn").addEventListener("click",async()=>{await fetch("/api/logout",{method:"POST"});window.location.href="/login";});function showErrors(errs){errorBox.innerHTML=Object.values(errs).map(m=>`<div>• ${m}</div>`).join("");errorBox.classList.remove("hidden");}function clearErrors(){errorBox.classList.add("hidden");errorBox.innerHTML="";}function resetForm(){postIdEl.value="";titleEl.value="";slugEl.value="";contentEl.value="";publishedEl.checked=true;formTitle.textContent="Tạo bài viết mới";cancelEdit.classList.add("hidden");clearErrors();}async function loadPosts(){const res=await fetch("/api/admin/posts",{headers:headers()});const json=await res.json();if(!json.ok){postsBody.innerHTML=`<tr><td colspan="4" class="py-4 text-center text-red-500">${json.error || "Unauthorized"}</td></tr>`;return;}if(json.data.length===0){postsBody.innerHTML=`<tr><td colspan="4" class="py-6 text-center text-slate-400">Chưa có bài viết nào</td></tr>`;return;}postsBody.innerHTML=json.data.map(p=>`
                <tr>
                    <td class="py-3 pr-3 font-mono text-xs text-slate-500">#${p.id}</td>
                    <td class="py-3 pr-3">
                        <div class="font-semibold text-slate-900">${p.title}</div>
                        <div class="text-xs text-slate-400 font-mono">/${p.slug}</div>
                    </td>
                    <td class="py-3 pr-3">
                        ${Number(p.published) === 1
                            ? `<span class="px-2 py-0.5 text-xs rounded-full bg-emerald-50 text-emerald-700 font-medium">Published</span>`
                            : `<span class="px-2 py-0.5 text-xs rounded-full bg-amber-50 text-amber-700 font-medium">Draft</span>`}
                    </td>
                    <td class="py-3 text-right space-x-2">
                        <button onclick="editPost(${p.id})" class="text-xs text-indigo-600 hover:underline font-medium">Sửa</button>
                        <button onclick="deletePost(${p.id})" class="text-xs text-red-600 hover:underline font-medium">Xoá</button>
